  (2, 'abandon', 'verb', 'b2', '6.0 - 6.5', '/əˈbændən/', '/əˈbændən/', 'từ bỏ, bỏ rơi, ruồng bỏ', 'to leave somebody, especially somebody you are responsible for, with no intention of returning', 'abandon somebody, The baby had been abandoned by its mother.', 'bỏ rơi ai đó, Đứa bé đã bị mẹ nó bỏ rơi.', ARRAY['abandon somebody', 'abandon hope', 'abandon a plan']::text[], ARRAY['give up', 'desert', 'forsake', 'relinquish']::text[], ARRAY['keep', 'maintain', 'retain', 'claim']::text[], '{"noun": "abandonment", "adjective": "abandoned"}'::jsonb, 'abandon_uk.mp3', 'abandon_us.mp3', 'People, Family & Relationships', 'Family & Relatives'),
