  (6, 'abortion', 'noun', 'c1', '7.0 - 8.0+', '/əˈbɔːʃn/', '/əˈbɔːrʃn/', 'sự sẩy thai, sự phá thai, sự nạo thai', 'the deliberate ending of a pregnancy at an early stage', 'to support/oppose abortion', 'ủng hộ/phản đối việc phá thai', ARRAY['support abortion', 'oppose abortion', 'have an abortion']::text[], ARRAY['termination', 'ending', 'conclusion', 'miscarriage']::text[], '{}'::text[], '{}'::jsonb, 'abortion_uk.mp3', 'abortion_us.mp3', 'Arts, Media & Entertainment', 'Cinema & Theatre'),
