  (21, 'abuse', 'verb', 'c1', '7.0 - 8.0+', '/əˈbjuːz/', '/əˈbjuːz/', 'sử dụng hoặc đối xử sai/tồi tệ, sự lạm dụng', 'to make bad use of something, or to use so much of something that it harms your health', 'to abuse alcohol/drugs', 'lạm dụng rượu/ma túy', ARRAY['drug abuse', 'child abuse', 'abuse of power']::text[], ARRAY['maltreatment', 'ill-treatment', 'ill-usage', 'mistreatment']::text[], '{}'::text[], '{}'::jsonb, 'abuse_uk.mp3', 'abuse_us.mp3', 'Academic, Research & Abstract Concepts', 'Abstract Ideas & Theories'),
  (22, 'academic', 'adjective', 'b1', '5.0 - 5.5', '/ˌækəˈdemɪk/', '/ˌækəˈdemɪk/', 'mang tính học thuật', 'connected with education, especially studying in schools and universities', 'high/low academic standards', 'tiêu chuẩn học tập cao/thấp', ARRAY['academic performance', 'academic year', 'academic research']::text[], ARRAY['world', 'domain', 'theoretical', 'donnish']::text[], '{}'::text[], '{"noun": "academy"}'::jsonb, 'academic_uk.mp3', 'academic_us.mp3', 'Education & Academic Life', 'Academic Life & Research'),
  (23, 'academic', 'noun', 'b2', '6.0 - 6.5', '/ˌækəˈdemɪk/', '/ˌækəˈdemɪk/', 'học giả, giảng viên đại học', 'a person who teaches and/or does research at a university or college', 'a leading/distinguished/prominent academic', 'một học giả hàng đầu/xuất sắc/nổi bật', ARRAY['academic performance', 'academic year', 'academic research']::text[], ARRAY['world', 'domain', 'theoretical', 'donnish']::text[], '{}'::text[], '{}'::jsonb, 'academic_uk.mp3', 'academic_us.mp3', 'Education & Academic Life', 'Academic Life & Research'),
  (24, 'academy', 'noun', 'c1', '7.0 - 8.0+', '/əˈkædəmi/', '/əˈkædəmi/', 'học viện, trường đào tạo đặc biệt', 'a school or college for special training', 'She trained at the Royal Academy of Music.', 'Cô được đào tạo tại Học viện Âm nhạc Hoàng gia.', ARRAY['police academy', 'military academy', 'naval academy']::text[], ARRAY['lyceum', 'lycee', 'Gymnasium', 'institution']::text[], '{}'::text[], '{"adjective": "academic"}'::jsonb, 'academy_uk.mp3', 'academy_us.mp3', 'Education & Academic Life', 'Schools & Universities'),
  (25, 'accelerate', 'verb', 'c1', '7.0 - 8.0+', '/əkˈseləreɪt/', '/əkˈseləreɪt/', 'làm nhanh thêm, làm chóng đến', 'to happen faster or earlier; to make something happen faster or earlier', 'Inflation continues to accelerate.', 'Lạm phát tiếp tục tăng tốc.', ARRAY['accelerate growth', 'accelerate progress', 'accelerate change']::text[], ARRAY['speed', 'quicken', 'intensify', 'deepen']::text[], ARRAY['decelerate']::text[], '{"noun": "accent", "adjective": "acceptable"}'::jsonb, 'accelerate_uk.mp3', 'accelerate_us.mp3', 'Academic, Research & Abstract Concepts', 'Abstract Ideas & Theories'),
  (26, 'accent', 'noun', 'b2', '6.0 - 6.5', '/ˈæksent/', '/ˈæksent/', 'giọng', 'a way of pronouncing the words of a language that shows which country, area or social class a person comes from; how well somebody pronounces a particular language', 'a northern/Dublin/Scottish accent', 'giọng miền bắc/Dublin/Scotland', ARRAY['foreign accent', 'heavy accent', 'native accent']::text[], ARRAY['pronunciation', 'emphasis', 'importance', 'grandness']::text[], '{}'::text[], '{"verb": "accelerate", "adjective": "acceptable"}'::jsonb, 'accent_uk.mp3', 'accent_us.mp3', 'Education & Academic Life', 'Subjects & Learning'),
  (27, 'accept', 'verb', 'a2', '4.0 - 4.5', '/əkˈsept/', '/əkˈsept/', 'nhận, chấp nhận, chấp thuận', 'to take willingly something that is offered; to say ‘yes’ to an offer, invitation, etc.', 'He asked me to marry him and I accepted.', 'Anh ấy ngỏ lời cầu hôn tôi và tôi đã chấp nhận.', ARRAY['accept an offer', 'accept responsibility', 'accept an invitation']::text[], ARRAY['judge', 'take', 'have', 'get']::text[], ARRAY['reject', 'refuse', 'decline']::text[], '{"noun": "acceptance", "adjective": "acceptable"}'::jsonb, 'accept_uk.mp3', 'accept_us.mp3', 'People, Family & Relationships', 'Marriage & Partnership'),
  (28, 'acceptable', 'adjective', 'b2', '6.0 - 6.5', '/əkˈseptəbl/', '/əkˈseptəbl/', '( acceptable to somebody ) có thể chấp nhận được, có thể thừa nhận', 'agreed or approved of by most people in a society', 'Children must learn socially acceptable behaviour.', 'Trẻ em phải học cách cư xử được xã hội chấp nhận.', ARRAY['acceptable behaviour']::text[], ARRAY['bankable', 'unexceptionable', 'unimpeachable', 'unobjectionable']::text[], ARRAY['unacceptable', 'unsatisfactory']::text[], '{"noun": "acceptance", "verb": "accept", "opposite": "unacceptable"}'::jsonb, 'acceptable_uk.mp3', 'acceptable_us.mp3', 'Society, Politics & Government', 'Civil Society & Human Rights'),
  (29, 'acceptance', 'noun', 'c1', '7.0 - 8.0+', '/əkˈseptəns/', '/əkˈseptəns/', 'sự nhận, sự chấp nhận, sự chấp thuận', 'the act of accepting a gift, an invitation, an offer, etc.', 'Please confirm your acceptance of this offer in writing.', 'Vui lòng xác nhận việc bạn chấp nhận lời đề nghị này bằng văn bản.', ARRAY['acceptance of this offer']::text[], ARRAY['credence', 'attitude', 'adoption', 'acceptation']::text[], ARRAY['rejection']::text[], '{"verb": "accelerate", "adjective": "acceptable"}'::jsonb, 'acceptance_uk.mp3', 'acceptance_us.mp3', 'Society, Politics & Government', 'Government Policy & Welfare'),
  (30, 'access', 'noun', 'b1', '5.0 - 5.5', '/ˈækses/', '/ˈækses/', 'lối vào, quyền truy cập', 'the opportunity or right to use something or to see somebody/something', 'High-speed internet access has become a necessity.', 'Truy cập internet tốc độ cao đã trở thành một điều cần thiết.', ARRAY['have access to', 'gain access to', 'internet access']::text[], ARRAY['entree', 'accession', 'admittance', 'right']::text[], '{}'::text[], '{"verb": "accelerate", "adjective": "acceptable"}'::jsonb, 'access_uk.mp3', 'access_us.mp3', 'Science, Technology & Computing', 'AI & Modern Tech'),
  (31, 'access', 'verb', 'b1', '5.0 - 5.5', '/ˈækses/', '/ˈækses/', 'truy cập (dữ liệu, hệ thống)', 'to open a computer file or use a computer system', 'Most people use their phones to access the internet.', 'Hầu hết mọi người sử dụng điện thoại của họ để truy cập internet.', ARRAY['have access to', 'gain access to', 'internet access']::text[], ARRAY['entree', 'accession', 'admittance', 'right']::text[], '{}'::text[], '{"noun": "accent", "adjective": "acceptable"}'::jsonb, 'access_uk.mp3', 'access_us.mp3', 'Science, Technology & Computing', 'Computer & Software'),
  (32, 'accessible', 'adjective', 'c1', '7.0 - 8.0+', '/əkˈsesəbl/', '/əkˈsesəbl/', '( accessible to somebody ) có thể tới được, sử dụng được...', 'that can be reached, entered, used, seen, etc.', 'The remote desert area is accessible only by helicopter.', 'Khu vực sa mạc xa xôi chỉ có thể đến được bằng trực thăng.', ARRAY['accessible only']::text[], ARRAY['approachable', 'reachable', 'come-at-able', 'get-at-able']::text[], ARRAY['inaccessible']::text[], '{"verb": "accelerate", "noun": "accent"}'::jsonb, 'accessible_uk.mp3', 'accessible_us.mp3', 'Environment, Climate & Nature', 'Geography & Landscape'),
  (33, 'accident', 'noun', 'a2', '4.0 - 4.5', '/ˈæksɪdənt/', '/ˈæksɪdənt/', 'sự rủi ro, tai nạn, tai biến', 'an unpleasant event, especially in a vehicle, that happens unexpectedly and causes injury or damage', 'a car/road/traffic accident', 'một vụ tai nạn ô tô/đường bộ/giao thông', ARRAY['car accident', 'fatal accident', 'by accident']::text[], ARRAY['mishap', 'misadventure', 'mischance', 'fortuity']::text[], '{}'::text[], '{"adverb": "accidentally"}'::jsonb, 'accident_uk.mp3', 'accident_us.mp3', 'Travel, Tourism & Transportation', 'Vehicles & Transit'),
  (34, 'accidentally', 'adverb', 'b2', '6.0 - 6.5', '/ˌæksɪˈdentəli/', '/ˌæksɪˈdentəli/', 'tình cờ, ngẫu nhiên', 'by chance; in a way that was not planned', 'As I turned around, I accidentally hit him in the face.', 'Khi tôi quay lại, tôi vô tình đánh vào mặt anh ta.', '{}'::text[], ARRAY['circumstantially', 'unexpectedly', 'incidentally', 'unintentionally']::text[], ARRAY['intentionally', 'deliberately']::text[], '{"noun": "accident"}'::jsonb, 'accidentally_uk.mp3', 'accidentally_us.mp3', 'Academic, Research & Abstract Concepts', 'Abstract Ideas & Theories'),
