  (242, 'annoying', 'adjective', 'b1', '5.0 - 5.5', '/əˈnɔɪɪŋ/', '/əˈnɔɪɪŋ/', 'làm trái ý, làm khó chịu, làm bực mình, chọc tức', 'making somebody feel slightly angry', 'This interruption is very annoying.', 'Sự gián đoạn này rất khó chịu.', '{}'::text[], ARRAY['bothersome', 'galling', 'irritating', 'nettlesome']::text[], '{}'::text[], '{"verb": "announce", "noun": "announcement"}'::jsonb, 'annoying_uk.mp3', 'annoying_us.mp3', 'Emotions, Personality & Behavior', 'Negative Emotions & Traits'),
  (243, 'annual', 'adjective', 'b2', '6.0 - 6.5', '/ˈænjuəl/', '/ˈænjuəl/', 'xảy ra hàng năm', 'happening or done once every year', 'an annual meeting/event/report/conference', 'một cuộc họp/sự kiện/báo cáo/hội nghị thường niên', ARRAY['annual meeting/event', 'annual meeting']::text[], ARRAY['yearly', 'recurring', 'per-year']::text[], ARRAY['biennial']::text[], '{"adverb": "annually"}'::jsonb, 'annual_uk.mp3', 'annual_us.mp3', 'Academic, Research & Abstract Concepts', 'Abstract Ideas & Theories'),
  (244, 'annually', 'adverb', 'b2', '6.0 - 6.5', '/ˈænjuəli/', '/ˈænjuəli/', 'hàng năm, mỗi năm', 'once a year', 'The exhibition is held annually.', 'Triển lãm được tổ chức hàng năm.', '{}'::text[], ARRAY['yearly', 'p.a.']::text[], '{}'::text[], '{"adjective": "annual"}'::jsonb, 'annually_uk.mp3', 'annually_us.mp3', 'Academic, Research & Abstract Concepts', 'Abstract Ideas & Theories'),
  (245, 'anonymous', 'adjective', 'c1', '7.0 - 8.0+', '/əˈnɒnɪməs/', '/əˈnɑːnɪməs/', 'giấu tên, ẩn danh, nặc danh', 'with a name that is not known or that is not made public', 'an anonymous donor', 'một nhà tài trợ ẩn danh', ARRAY['anonymous donor']::text[], ARRAY['unnamed', 'unidentified', 'nameless']::text[], ARRAY['onymous']::text[], '{}'::jsonb, 'anonymous_uk.mp3', 'anonymous_us.mp3', 'Society, Politics & Government', 'Civil Society & Human Rights'),
  (246, 'another', 'determiner', 'a1', '3.0 - 3.5', '/əˈnʌðə(r)/', '/əˈnʌðər/', '(một người hoặc vật) khác', 'one more; an extra thing or person', 'Would you like another drink?', 'Bạn có muốn đồ uống khác không?', '{}'::text[], ARRAY['different', 'other', 'additional', 'added']::text[], '{}'::text[], '{}'::jsonb, 'another_uk.mp3', 'another_us.mp3', 'Discourse Markers & Connectors', 'Pronouns & Determiners'),
  (247, 'another', 'pronoun', 'a1', '3.0 - 3.5', '/əˈnʌðə(r)/', '/əˈnʌðər/', '(một người hoặc vật) khác', 'one more; an extra thing or person', 'Would you like another drink?', 'Bạn có muốn đồ uống khác không?', '{}'::text[], '{}'::text[], '{}'::text[], '{}'::jsonb, 'another_uk.mp3', 'another_us.mp3', 'Numbers, Measurements & Data Trends', 'Numbers & Quantity'),
  (248, 'answer', 'noun', 'a1', '3.0 - 3.5', '/ˈɑːnsə(r)/', '/ˈænsər/', 'câu trả lời, ( answer to somebody / something ) sự trả lời', 'something that you say, write or do to react to a question or situation', 'I rang the bell, but there was no answer.', 'Tôi bấm chuông nhưng không có câu trả lời.', '{}'::text[], ARRAY['reply', 'response']::text[], ARRAY['question']::text[], '{}'::jsonb, 'answer_uk.mp3', 'answer_us.mp3', 'Academic, Research & Abstract Concepts', 'Abstract Ideas & Theories'),
  (249, 'answer', 'verb', 'a1', '3.0 - 3.5', '/ˈɑːnsə(r)/', '/ˈænsər/', 'câu trả lời, ( answer to somebody / something ) sự trả lời', 'to say, write or do something as a reaction to a question or situation', 'I repeated the question, but she didn''t answer.', 'Tôi lặp lại câu hỏi nhưng cô ấy không trả lời.', '{}'::text[], ARRAY['reply', 'response']::text[], ARRAY['question']::text[], '{}'::jsonb, 'answer_uk.mp3', 'answer_us.mp3', 'Academic, Research & Abstract Concepts', 'Abstract Ideas & Theories'),
  (250, 'anticipate', 'verb', 'b2', '6.0 - 6.5', '/ænˈtɪsɪpeɪt/', '/ænˈtɪsɪpeɪt/', 'thấy trước, biết trước, đoán trước, dè trước, chặn trước, liệu trước, lường trước', 'to expect something', 'anticipate something, We don''t anticipate any major problems.', 'dự đoán điều gì đó, Chúng tôi không lường trước bất kỳ vấn đề lớn nào.', ARRAY['anticipate problems', 'eagerly anticipate']::text[], ARRAY['expect', 'foresee', 'predict']::text[], '{}'::text[], '{}'::jsonb, 'anticipate_uk.mp3', 'anticipate_us.mp3', 'Academic, Research & Abstract Concepts', 'Abstract Ideas & Theories')
INSERT INTO public.words (id, word, type, cefr, ielts_band, phon_br, phon_n_am, meaning_vi, definition, example, example_vi, collocations, synonyms, antonyms, word_family, uk, us, topic, subtopic) VALUES
  (251, 'anxiety', 'noun', 'b2', '6.0 - 6.5', '/æŋˈzaɪəti/', '/æŋˈzaɪəti/', 'mối lo âu, mối băn khoăn', 'the state of feeling nervous or worried that something bad is going to happen', 'acute/intense/deep anxiety', 'lo lắng cấp tính/cực kỳ/sâu sắc', ARRAY['acute/intense/deep anxiety']::text[], ARRAY['worry', 'unease', 'apprehension']::text[], '{}'::text[], '{"adjective": "anxious"}'::jsonb, 'anxiety_uk.mp3', 'anxiety_us.mp3', 'Emotions, Personality & Behavior', 'Negative Emotions & Traits'),
  (252, 'anxious', 'adjective', 'b2', '6.0 - 6.5', '/ˈæŋkʃəs/', '/ˈæŋkʃəs/', '( anxious about / for somebody / something ) lo âu, băn khoăn', 'feeling worried or nervous', 'The bus was late and Sue began to get anxious.', 'Xe buýt đến trễ và Sue bắt đầu lo lắng.', '{}'::text[], ARRAY['apprehensive', 'uneasy', 'dying', 'eager']::text[], '{}'::text[], '{"noun": "anxiety"}'::jsonb, 'anxious_uk.mp3', 'anxious_us.mp3', 'Emotions, Personality & Behavior', 'Negative Emotions & Traits'),
  (253, 'any', 'adverb', 'a2', '4.0 - 4.5', '/ˈeni/', '/ˈeni/', 'bất cứ', 'used to emphasize an adjective or adverb in negative sentences or questions, meaning ‘at all’', 'He wasn''t any good at French.', 'Anh ấy không giỏi tiếng Pháp chút nào.', '{}'::text[], ARRAY['immoderate', 'whatever', 'whatsoever', 'some']::text[], '{}'::text[], '{}'::jsonb, 'any_uk.mp3', 'any_us.mp3', 'Academic, Research & Abstract Concepts', 'Abstract Ideas & Theories'),
  (254, 'any', 'determiner', 'a1', '3.0 - 3.5', '/ˈeni/', '/ˈeni/', 'bất cứ', 'used with uncountable or plural nouns in negative sentences and questions, after if or whether, and after some verbs such as prevent, ban, forbid, etc. to refer to an amount or a number of something, however large or small', 'I didn''t eat any meat.', 'Tôi không ăn chút thịt nào.', '{}'::text[], ARRAY['immoderate', 'whatever', 'whatsoever', 'some']::text[], '{}'::text[], '{"adverb": "any more"}'::jsonb, 'any_uk.mp3', 'any_us.mp3', 'Discourse Markers & Connectors', 'Pronouns & Determiners'),
  (255, 'any', 'pronoun', 'a1', '3.0 - 3.5', '/ˈeni/', '/ˈeni/', 'bất cứ', 'used in negative sentences and in questions and after if or whether to refer to an amount or a number, however large or small', 'We need some more paint; there isn''t any left.', 'Chúng ta cần sơn thêm; không còn lại chút nào.', '{}'::text[], '{}'::text[], '{}'::text[], '{"adverb": "any more"}'::jsonb, 'any_uk.mp3', 'any_us.mp3', 'Discourse Markers & Connectors', 'Pronouns & Determiners'),
  (256, 'any more', 'adverb', 'a2', '4.0 - 4.5', '/ˌeni ˈmɔː(r)/', '/ˌeni ˈmɔːr/', 'nữa, thêm nữa', 'often used at the end of negative sentences and at the end of questions, to mean ‘any longer’', 'She doesn''t live here any more.', 'Cô ấy không còn sống ở đây nữa.', '{}'::text[], '{}'::text[], '{}'::text[], '{}'::jsonb, 'any more_uk.mp3', 'any more_us.mp3', 'Emotions, Personality & Behavior', 'Interpersonal Behavior'),
  (257, 'anybody', 'pronoun', 'a2', '4.0 - 4.5', '/ˈenibɒdi/', '/ˈenibɑːdi/', 'bất cứ ai', 'used instead of somebody in negative sentences and in questions after if/whether, and after verbs such as prevent, forbid, avoid, etc.', 'Is there anybody who can help me?', 'Có ai có thể giúp tôi không?', '{}'::text[], '{}'::text[], '{}'::text[], '{}'::jsonb, 'anybody_uk.mp3', 'anybody_us.mp3', 'Academic, Research & Abstract Concepts', 'Abstract Ideas & Theories'),
  (258, 'anyone', 'pronoun', 'a1', '3.0 - 3.5', '/ˈeniwʌn/', '/ˈeniwʌn/', 'xem anybody', 'used instead of someone in negative sentences and in questions after if/whether, and after verbs such as prevent, forbid, avoid, etc.', 'Is anyone there?', 'Có ai ở đó không?', '{}'::text[], '{}'::text[], '{}'::text[], '{}'::jsonb, 'anyone_uk.mp3', 'anyone_us.mp3', 'Academic, Research & Abstract Concepts', 'Abstract Ideas & Theories'),
  (259, 'anything', 'pronoun', 'a1', '3.0 - 3.5', '/ˈeniθɪŋ/', '/ˈeniθɪŋ/', 'bất cứ cái gì (trong câu phủ định và câu hỏi)', 'used instead of something in negative sentences and in questions; after if/whether; and after verbs such as prevent, ban, avoid, etc.', 'Would you like anything else?', 'Bạn có muốn điều gì khác không?', '{}'::text[], '{}'::text[], '{}'::text[], '{}'::jsonb, 'anything_uk.mp3', 'anything_us.mp3', 'Academic, Research & Abstract Concepts', 'Abstract Ideas & Theories'),
  (260, 'anyway', 'adverb', 'a2', '4.0 - 4.5', '/ˈeniweɪ/', '/ˈeniweɪ/', 'như anyhow 2', 'used when adding something to support an idea or argument', 'It''s too expensive and anyway the colour doesn''t suit you.', 'Nó quá đắt và dù sao thì màu sắc cũng không hợp với bạn.', '{}'::text[], ARRAY['anyhow']::text[], '{}'::text[], '{}'::jsonb, 'anyway_uk.mp3', 'anyway_us.mp3', 'Academic, Research & Abstract Concepts', 'Abstract Ideas & Theories'),
  (261, 'anywhere', 'adverb', 'a2', '4.0 - 4.5', '/ˈeniweə(r)/', '/ˈeniwer/', 'bất kỳ chỗ nào, bất cứ nơi đâu', 'used in negative sentences and in questions instead of somewhere', 'I can''t see it anywhere.', 'Tôi không thể nhìn thấy nó ở bất cứ đâu.', '{}'::text[], ARRAY['anyplace']::text[], '{}'::text[], '{}'::jsonb, 'anywhere_uk.mp3', 'anywhere_us.mp3', 'Academic, Research & Abstract Concepts', 'Abstract Ideas & Theories'),
  (262, 'anywhere', 'pronoun', 'a2', '4.0 - 4.5', '/ˈeniweə(r)/', '/ˈeniwer/', 'bất kỳ chỗ nào, bất cứ nơi đâu', 'used in negative sentences and in questions instead of somewhere', 'I don''t have anywhere to stay.', 'Tôi không có nơi nào để ở.', ARRAY['anywhere to stay']::text[], '{}'::text[], '{}'::text[], '{"adverb": "anyway"}'::jsonb, 'anywhere_uk.mp3', 'anywhere_us.mp3', 'Academic, Research & Abstract Concepts', 'Abstract Ideas & Theories'),
  (263, 'apart', 'adverb', 'b1', '5.0 - 5.5', '/əˈpɑːt/', '/əˈpɑːrt/', 'về hoặc ở một phía, riêng ra', 'separated by a distance, of space or time', 'The two houses stood 500 metres apart.', 'Hai nhà cách nhau 500m.', '{}'::text[], ARRAY['isolated', 'obscure', 'unconnected', 'separate']::text[], '{}'::text[], '{"noun": "apartment"}'::jsonb, 'apart_uk.mp3', 'apart_us.mp3', 'Numbers, Measurements & Data Trends', 'Sizes, Dimensions & Weight'),
  (264, 'apartment', 'noun', 'a1', '3.0 - 3.5', '/əˈpɑːtmənt/', '/əˈpɑːrtmənt/', 'buồng, căn phòng, căn hộ', 'a set of rooms for living in, usually on one floor of a building', 'an apartment building', 'một tòa nhà chung cư', '{}'::text[], ARRAY['flat', 'housing', 'lodging']::text[], '{}'::text[], '{"adverb": "apart"}'::jsonb, 'apartment_uk.mp3', 'apartment_us.mp3', 'Housing, Architecture & Daily Life', 'Buildings & Structures'),
  (265, 'apologize', 'verb', 'b1', '5.0 - 5.5', '/əˈpɒlədʒaɪz/', '/əˈpɑːlədʒaɪz/', 'xin lỗi, tạ lỗi', 'to say that you are sorry for doing something wrong or causing a problem', 'Why should I apologize?', 'Tại sao tôi phải xin lỗi?', '{}'::text[], ARRAY['say sorry', 'express regret', 'ask forgiveness']::text[], '{}'::text[], '{"noun": "apology"}'::jsonb, 'apologize_uk.mp3', 'apologize_us.mp3', 'Academic, Research & Abstract Concepts', 'Abstract Ideas & Theories'),
  (266, 'apology', 'noun', 'b2', '6.0 - 6.5', '/əˈpɒlədʒi/', '/əˈpɑːlədʒi/', 'lời xin lỗi, ( apology to somebody for something ) lời tạ lỗi', 'a word or statement saying sorry for something that has been done wrong or that causes a problem', 'to offer/make/demand/accept an apology', 'đề nghị/thực hiện/yêu cầu/chấp nhận một lời xin lỗi', ARRAY['to offer/make', 'demand/accept an']::text[], ARRAY['acknowledgment', 'acknowledgement', 'apologia', 'defense']::text[], '{}'::text[], '{"verb": "apologize"}'::jsonb, 'apology_uk.mp3', 'apology_us.mp3', 'Business, Trade & Finance', 'Commerce & Retail'),
  (267, 'app', 'noun', 'a2', '4.0 - 4.5', '/æp/', '/æp/', 'ứng dụng', 'a piece of software that you can download to a device such as a smartphone or tablet, for example to look up information or to play a game', 'You first need to install the app on your device.', 'Trước tiên, bạn cần cài đặt ứng dụng trên thiết bị của mình.', ARRAY['app on your device']::text[], '{}'::text[], '{}'::text[], '{"adjective": "apparent", "verb": "appeal"}'::jsonb, 'app_uk.mp3', 'app_us.mp3', 'Science, Technology & Computing', 'AI & Modern Tech'),
  (268, 'apparatus', 'noun', 'c1', '7.0 - 8.0+', '/ˌæpəˈreɪtəs/', '/ˌæpəˈrætəs/', 'bộ máy, (sinh vật học) hệ thống các bộ phận trong cơ thể', 'the tools or other pieces of equipment that are needed for a particular activity or task', 'a piece of laboratory apparatus', 'một bộ máy thí nghiệm', '{}'::text[], ARRAY['equipment', 'device', 'machinery']::text[], '{}'::text[], '{"adjective": "apparent", "adverb": "apparently"}'::jsonb, 'apparatus_uk.mp3', 'apparatus_us.mp3', 'Science, Technology & Computing', 'Scientific Methods & Research'),
  (269, 'apparent', 'adjective', 'b2', '6.0 - 6.5', '/əˈpærənt/', '/əˈpærənt/', 'rõ ràng, bày tỏ ra ngoài, thấy rõ ra ngoài', 'easy to see or understand', 'Their devotion was apparent.', 'Sự tận tâm của họ là rõ ràng.', '{}'::text[], ARRAY['obvious', 'evident', 'clear', 'visible']::text[], '{}'::text[], '{"noun": "apparatus", "adverb": "apparently"}'::jsonb, 'apparent_uk.mp3', 'apparent_us.mp3', 'Academic, Research & Abstract Concepts', 'Abstract Ideas & Theories'),
  (270, 'apparently', 'adverb', 'b2', '6.0 - 6.5', '/əˈpærəntli/', '/əˈpærəntli/', 'nhìn bên ngoài, hình như', 'according to what you have heard or read; according to the way something appears', 'Apparently they are getting divorced soon.', 'Có vẻ như họ sẽ sớm ly hôn.', '{}'::text[], ARRAY['seemingly', 'ostensibly', 'obviously', 'evidently']::text[], '{}'::text[], '{"noun": "apparatus", "adjective": "apparent"}'::jsonb, 'apparently_uk.mp3', 'apparently_us.mp3', 'Academic, Research & Abstract Concepts', 'Abstract Ideas & Theories'),
  (271, 'appeal', 'noun', 'b2', '6.0 - 6.5', '/əˈpiːl/', '/əˈpiːl/', 'sự hấp dẫn, sự thích thú', 'a deeply felt request for money, help or information that is needed immediately, especially one made by a charity or by the police', 'appeal for something, to launch a TV appeal for donations to the charity', 'kêu gọi điều gì đó, phát động một chương trình truyền hình kêu gọi quyên góp cho tổ chức từ thiện', ARRAY['appeal for something', 'appeal for donations to']::text[], ARRAY['attract', 'entice', 'draw']::text[], ARRAY['repel']::text[], '{"adjective": "appealing", "verb": "appear"}'::jsonb, 'appeal_uk.mp3', 'appeal_us.mp3', 'Law, Crime & Justice', 'Court & Trials'),
  (272, 'appeal', 'verb', 'b2', '6.0 - 6.5', '/əˈpiːl/', '/əˈpiːl/', 'hấp dẫn, sự thích thú', 'to make a deeply felt request, especially for something that is needed immediately', 'I am appealing (= asking for money) on behalf of the famine victims.', 'Tôi đang kêu gọi (= xin tiền) thay mặt cho các nạn nhân nạn đói.', '{}'::text[], ARRAY['attract', 'entice', 'draw']::text[], ARRAY['repel']::text[], '{"adjective": "appealing", "noun": "appearance"}'::jsonb, 'appeal_uk.mp3', 'appeal_us.mp3', 'Law, Crime & Justice', 'Court & Trials'),
  (273, 'appealing', 'adjective', 'c1', '7.0 - 8.0+', '/əˈpiːlɪŋ/', '/əˈpiːlɪŋ/', 'van lơn, cầu khẩn', 'attractive or interesting', 'Spending the holidays in Britain wasn''t a prospect that I found particularly appealing.', 'Việc dành những ngày nghỉ ở Anh không phải là một viễn cảnh mà tôi thấy đặc biệt hấp dẫn.', '{}'::text[], ARRAY['attention-getting', 'catchy', 'attractive', 'sympathetic']::text[], ARRAY['repel', 'unsympathetic', 'unappealing']::text[], '{"noun": "appeal", "verb": "appeal"}'::jsonb, 'appealing_uk.mp3', 'appealing_us.mp3', 'Appearance, Clothes & Fashion', 'Physical Appearance'),
  (274, 'appear', 'verb', 'a2', '4.0 - 4.5', '/əˈpɪə(r)/', '/əˈpɪr/', 'xuất hiện, hiện ra, ló ra', 'to start to be seen', 'Three days later a rash appeared.', 'Ba ngày sau, phát ban xuất hiện.', '{}'::text[], ARRAY['look', 'seem', 'be', 'happen']::text[], ARRAY['disappear', 'vanish']::text[], '{"noun": "appeal", "adjective": "appealing"}'::jsonb, 'appear_uk.mp3', 'appear_us.mp3', 'Numbers, Measurements & Data Trends', 'Numbers & Quantity'),
  (275, 'appearance', 'noun', 'a2', '4.0 - 4.5', '/əˈpɪərəns/', '/əˈpɪrəns/', 'sự xuất hiện, sự hiện ra', 'the way that somebody/something looks on the outside; what somebody/something seems to be', 'the physical/outward/external appearance of something', 'hình dáng vật lý/bên ngoài/bên ngoài của cái gì đó', ARRAY['appearance of something', 'the physical/outward']::text[], ARRAY['quality', 'happening', 'occurrence', 'appearing']::text[], ARRAY['disappearance']::text[], '{"verb": "appeal", "adjective": "appealing"}'::jsonb, 'appearance_uk.mp3', 'appearance_us.mp3', 'Appearance, Clothes & Fashion', 'Physical Appearance'),
  (276, 'appetite', 'noun', 'c1', '7.0 - 8.0+', '/ˈæpɪtaɪt/', '/ˈæpɪtaɪt/', 'sự ngon miệng, sự thèm ăn', 'physical desire for food', 'He suffered from headaches and loss of appetite.', 'Anh ấy bị đau đầu và chán ăn.', '{}'::text[], ARRAY['appetency', 'appetence', 'craving']::text[], '{}'::text[], '{"verb": "appeal", "adjective": "appealing"}'::jsonb, 'appetite_uk.mp3', 'appetite_us.mp3', 'Food, Cooking & Hospitality', 'Taste & Flavors'),
